import type { FetchConfig } from 'insomnia-api';

import { OFFLINE_SERVICE_ERROR } from './offline-policy';

type FetchImplementation = (input: string, init?: RequestInit) => Promise<Response>;

/** Keep the bootstrap interface, but do not retain an online fetch implementation. */
export function setFetchImplementation(_impl: FetchImplementation): void {}

/** Insomnia's service SDK transport, NOT the user's API-request transport. */
export const proxyAwareFetch: typeof globalThis.fetch = async () => {
  throw new Error(OFFLINE_SERVICE_ERROR);
};

export async function insomniaFetch<T = void>(
  _options: FetchConfig & { retries?: number; onDeepLink?: (uri: string) => void },
): Promise<T> {
  throw new Error(OFFLINE_SERVICE_ERROR);
}

import type { AnalyticsEvent } from 'insomnia-analytics';

export { AnalyticsEvent } from 'insomnia-analytics';

// Intentionally no analytics client, identifiers, queue, timers, disk spool or transport.
export function setCurrentOrganizationId(_id: string | undefined): void {}
export async function trackAnalyticsEvent(_event: AnalyticsEvent, _properties?: Record<string, unknown>): Promise<void> {}
export async function trackPageView(_name: string): Promise<void> {}

// No Sentry SDK initialization, persistent envelope queue, crash uploads or DB observer.
export function initializeSentry(): void {}
export function sentryWatchAnalyticsEnabled(): void {}

import { BrowserWindow } from 'electron';

import { ipcMainOn } from './ipc/electron';

export const getUpdatesBaseURL = '';
export const getUpdateUrl = (_updateChannel: string): string | null => null;
let initialized = false;

// Keep IPC replies deterministic; never import either updater or start a timer.
export const init = async (): Promise<void> => {
  if (initialized) return;
  initialized = true;
  ipcMainOn('getUpdateStatus', event => {
    event.returnValue = 'idle';
  });
  ipcMainOn('applyUpdateAndRestart', () => {});
  ipcMainOn('manualUpdateCheck', () => {
    for (const window of BrowserWindow.getAllWindows()) {
      window.webContents.send('update-status-changed', 'idle');
      window.webContents.send('show-toast', {
        content: {
          title: 'Updates are disabled in this offline build',
          description: 'Install a separately reviewed offline package to upgrade.',
          status: 'info',
        },
      });
    }
  });
};

import path from 'node:path';
import { pathToFileURL } from 'node:url';

import { app, net, protocol } from 'electron';

import { OFFLINE_APP_ORIGIN } from '../common/offline-policy';
import { assertOfflineBrowserRequest } from './offline-network';
import { resolveDbByKey } from './templating-worker-database';

export interface RegisterProtocolOptions {
  scheme: string;
}

const insomniaStreamScheme = 'insomnia-event-source';
const templatingWorkerDatabaseInterface = 'insomnia-templating-worker-database';

export async function registerInsomniaProtocols() {
  protocol.registerSchemesAsPrivileged([
    { scheme: insomniaStreamScheme, privileges: { secure: true, standard: true, supportFetchAPI: true, stream: true, corsEnabled: true } },
    { scheme: 'https', privileges: { secure: true, standard: true, supportFetchAPI: true } },
    { scheme: 'http', privileges: { secure: true, standard: true, supportFetchAPI: true } },
    { scheme: templatingWorkerDatabaseInterface, privileges: { secure: true, standard: true, supportFetchAPI: true, corsEnabled: true } },
  ]);
  await app.whenReady();

  // This custom scheme is the product's cloud event stream, not user-created SSE requests.
  // Removing the native Curl forwarding path is essential: webRequest alone cannot cover it.
  if (!protocol.isProtocolHandled(insomniaStreamScheme)) {
    protocol.handle(insomniaStreamScheme, () => new Response('Cloud event stream disabled', { status: 503 }));
  }

  const handleBrowserRequest = async (request: Request): Promise<Response> => {
    try {
      assertOfflineBrowserRequest(request.url);
      const url = new URL(request.url);
      if (url.origin === OFFLINE_APP_ORIGIN) {
        const rootDir = path.resolve(__dirname, 'client');
        const pathname = decodeURIComponent(url.pathname);
        const filePath = pathname.startsWith('/assets/')
          ? path.resolve(rootDir, `.${pathname}`)
          : path.join(rootDir, 'index.html');
        if (!filePath.startsWith(rootDir + path.sep)) return new Response('Forbidden', { status: 403 });
        return await net.fetch(pathToFileURL(filePath).href, { bypassCustomProtocolHandlers: true });
      }
      // Only explicit administrator origins (and exact Vite dev origin) reach this branch.
      // The per-session webRequest policy rechecks redirected URLs.
      return await net.fetch(request, { bypassCustomProtocolHandlers: true });
    } catch {
      return new Response('Blocked by offline browser policy', { status: 403 });
    }
  };
  for (const scheme of ['https', 'http']) {
    if (!protocol.isProtocolHandled(scheme)) protocol.handle(scheme, handleBrowserRequest);
  }
  if (!protocol.isProtocolHandled(templatingWorkerDatabaseInterface)) {
    protocol.handle(templatingWorkerDatabaseInterface, resolveDbByKey);
  }
}

import type { CurrentPlan, Organization, User } from 'insomnia-api';
import { useCallback } from 'react';

import { OFFLINE_ORGANIZATION } from '~/common/offline';

/** Local organization metadata, not a fabricated server account or paid subscription. */
export function useOrganizations(): Organization[] {
  return [OFFLINE_ORGANIZATION];
}
export function useCurrentUser(): User | undefined {
  return undefined;
}
export function useCurrentPlan(): CurrentPlan | undefined {
  return undefined;
}
export function useInvalidateAccountData() {
  return useCallback(async () => {}, []);
}

import type { StorageRules } from 'insomnia-api';

export const DEFAULT_STORAGE_RULES: StorageRules = {
  enableCloudSync: false,
  enableLocalVault: true,
  enableGitSync: false,
  isOverridden: false,
};

export async function fetchAndCacheOrganizationStorageRule(
  _organizationId: string | undefined,
  _forceFetch = false,
): Promise<StorageRules> {
  return { ...DEFAULT_STORAGE_RULES };
}
